#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

ll modinv(ll a, ll m) {
    ll x, y;
    extgcd(a, m, x, y);
    x %= m;
    if (x < 0) x += m;
    return x;
}

int main(){
    int n;
    cin >> n;
    vector<ll> r(n), m(n);
    for (int i = 0; i < n; i++) cin >> r[i] >> m[i];
    // moduli are guaranteed pairwise coprime
    lll M = 1;
    for (int i = 0; i < n; i++) M *= m[i];
    lll x = 0;
    for (int i = 0; i < n; i++) {
        lll Mi = M / m[i];
        ll Mi_mod = (ll)(Mi % m[i]);
        ll inv = modinv(Mi_mod, m[i]);
        x += Mi * ((lll)((r[i] * (lll)inv) % m[i]));
    }
    x %= M;
    if (x < 0) x += M;
    // print x (fits since we only test with values fitting in long long for this example)
    ll xl = (ll)x;
    ll Ml = (ll)M;
    cout << xl << " " << Ml << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

ll extgcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = extgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

// merge x=r1 (mod m1) and x=r2 (mod m2) into x=r (mod lcm); works even when gcd(m1,m2) > 1
bool merge(ll r1, ll m1, ll r2, ll m2, ll &r, ll &m) {
    ll p, q;
    ll g = extgcd(m1, m2, p, q);
    if (((r2 - r1) % g + g) % g != 0) return false; // inconsistent residues
    ll mod2 = m2 / g;
    lll t = ((lll)(((r2 - r1) / g) % mod2) * (p % mod2)) % mod2;
    ll tt = (ll)((t % mod2 + mod2) % mod2);
    ll lcm = m1 / g * m2;
    ll x = (ll)(((lll)r1 + (lll)m1 * tt) % lcm);
    if (x < 0) x += lcm;
    r = x; m = lcm;
    return true;
}

int main(){
    int n;
    cin >> n;
    ll curR = 0, curM = 1;
    for (int i = 0; i < n; i++) {
        ll r, m;
        cin >> r >> m;
        ll nr, nm;
        if (!merge(curR, curM, r, m, nr, nm)) { cout << -1 << endl; return 0; }
        curR = nr; curM = nm;
    }
    cout << curR << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;
const int K = 6;

typedef vector<vector<ll>> Mat;

Mat matmul(const Mat &A, const Mat &B) {
    int n = A.size(), m = B[0].size(), k = B.size();
    Mat C(n, vector<ll>(m, 0));
    for (int i = 0; i < n; i++)
        for (int t = 0; t < k; t++) {
            if (A[i][t] == 0) continue;
            for (int j = 0; j < m; j++)
                C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % MOD;
        }
    return C;
}

Mat matpow(Mat A, ll p) {
    int n = A.size();
    Mat R(n, vector<ll>(n, 0));
    for (int i = 0; i < n; i++) R[i][i] = 1;
    while (p > 0) {
        if (p & 1) R = matmul(R, A);
        A = matmul(A, A);
        p >>= 1;
    }
    return R;
}

int main(){
    ll n;
    cin >> n;
    // f(0) = 1, f(negative) = 0, f(i) = sum_{d=1}^{6} f(i-d)
    if (n == 0) { cout << 1 << endl; return 0; }
    // base vector for indices [1..6] via direct DP if n small, else matrix expo
    ll limit = min(n, (ll)6);
    vector<ll> f(limit + 1, 0);
    f[0] = 1;
    for (ll i = 1; i <= limit; i++) {
        ll s = 0;
        for (int d = 1; d <= 6 && d <= i; d++) s = (s + f[i-d]) % MOD;
        f[i] = s;
    }
    if (n <= 6) { cout << f[n] << endl; return 0; }
    // transition matrix for state vector [f(i), f(i-1), ..., f(i-5)]
    Mat T(K, vector<ll>(K, 0));
    for (int j = 0; j < K; j++) T[0][j] = 1;
    for (int i = 1; i < K; i++) T[i][i-1] = 1;
    // state at i=6: [f(6),f(5),f(4),f(3),f(2),f(1)]
    vector<ll> state = {f[6], f[5], f[4], f[3], f[2], f[1]};
    Mat Tp = matpow(T, n - 6);
    ll ans = 0;
    for (int j = 0; j < K; j++) ans = (ans + Tp[0][j] * state[j]) % MOD;
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;
typedef vector<vector<ll>> Mat;

Mat matmul(const Mat &A, const Mat &B) {
    int n = A.size(), m = B[0].size(), k = B.size();
    Mat C(n, vector<ll>(m, 0));
    for (int i = 0; i < n; i++)
        for (int t = 0; t < k; t++) {
            if (A[i][t] == 0) continue;
            for (int j = 0; j < m; j++)
                C[i][j] = (C[i][j] + A[i][t] * B[t][j]) % MOD;
        }
    return C;
}
Mat matpow(Mat A, ll p) {
    int n = A.size();
    Mat R(n, vector<ll>(n, 0));
    for (int i = 0; i < n; i++) R[i][i] = 1;
    while (p > 0) {
        if (p & 1) R = matmul(R, A);
        A = matmul(A, A);
        p >>= 1;
    }
    return R;
}

int main(){
    ll n; int M;
    cin >> n >> M;
    // f(i) = 1 for 0 <= i < M ; f(i) = f(i-1) + f(i-M) for i >= M
    vector<ll> f(min(n, (ll)M) + 1, 0);
    for (ll i = 0; i <= min(n, (ll)(M-1)); i++) f[i] = 1;
    if (n < M) { cout << f[n] << endl; return 0; }
    // compute f[0..M] directly with simple DP (small, only M+1 terms needed as base state)
    vector<ll> full(M+1);
    for (int i = 0; i < M; i++) full[i] = 1;
    full[M] = (full[M-1] + full[0]) % MOD; // f(M) = f(M-1) + f(0)
    if (n == M) { cout << full[M] << endl; return 0; }
    // state vector at index M: [f(M), f(M-1), ..., f(M-M+1)] = [f(M), f(M-1), ..., f(1)]
    vector<ll> state(M);
    for (int j = 0; j < M; j++) state[j] = full[M - j];
    // transition matrix T (M x M): new[0] = old[0] + old[M-1] (f(i)=f(i-1)+f(i-M))
    // state = [f(i), f(i-1), ..., f(i-M+1)]
    // next state = [f(i+1), f(i), ..., f(i-M+2)] where f(i+1) = f(i) + f(i-M+1) = state[0] + state[M-1]
    Mat T(M, vector<ll>(M, 0));
    T[0][0] = 1; T[0][M-1] = 1;
    for (int i = 1; i < M; i++) T[i][i-1] = 1;
    Mat Tp = matpow(T, n - M);
    ll ans = 0;
    for (int j = 0; j < M; j++) ans = (ans + Tp[0][j] * state[j]) % MOD;
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll P; // prime modulus
vector<ll> fact, inv_fact;

ll power(ll a, ll e, ll mod) {
    a %= mod; if (a < 0) a += mod;
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return r;
}

void precompute(ll p) {
    fact.assign(p, 1);
    for (ll i = 1; i < p; i++) fact[i] = fact[i-1] * i % p;
    inv_fact.assign(p, 1);
    inv_fact[p-1] = power(fact[p-1], p-2, p);
    for (ll i = p-1; i >= 1; i--) inv_fact[i-1] = inv_fact[i] * i % p;
}

// C(n, k) mod p for small n, k < p
ll smallComb(ll n, ll k, ll p) {
    if (k < 0 || k > n) return 0;
    return fact[n] * inv_fact[k] % p * inv_fact[n-k] % p;
}

// Lucas' theorem: C(n, k) mod p for huge n, k, prime p
ll lucas(ll n, ll k, ll p) {
    if (k == 0) return 1;
    ll ni = n % p, ki = k % p;
    if (ki > ni) return 0;
    return smallComb(ni, ki, p) * lucas(n / p, k / p, p) % p;
}

int main(){
    ll n, k, p;
    cin >> n >> k >> p;
    precompute(p);
    cout << lucas(n, k, p) << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main(){
    int n;
    cin >> n;
    vector<int> a(n);
    int maxV = 1;
    for (auto &x : a) { cin >> x; maxV = max(maxV, x); }

    // sieve smallest prime factor for Mobius function
    vector<int> spf(maxV+1, 0);
    for (int i = 2; i <= maxV; i++) {
        if (spf[i] == 0) {
            for (int j = i; j <= maxV; j += i) {
                if (spf[j] == 0) spf[j] = i;
            }
        }
    }
    vector<int> mu(maxV+1, 0);
    mu[1] = 1;
    for (int i = 2; i <= maxV; i++) {
        int x = i / spf[i];
        if (x % spf[i] == 0) mu[i] = 0; // squared prime factor
        else mu[i] = -mu[x];
    }

    // cnt[d] = number of array elements divisible by d
    vector<ll> cnt(maxV+1, 0);
    vector<ll> freq(maxV+1, 0);
    for (int x : a) freq[x]++;
    for (int d = 1; d <= maxV; d++) {
        for (int m = d; m <= maxV; m += d) cnt[d] += freq[m];
    }

    // answer = sum_d mu(d) * C(cnt[d], 2)
    ll ans = 0;
    for (int d = 1; d <= maxV; d++) {
        if (mu[d] == 0) continue;
        ll c = cnt[d];
        ans += (ll)mu[d] * (c * (c-1) / 2);
    }
    cout << ans << endl;
}
